let pdiSugs=[];
A.pdiIA=async d=>{const x=S.pdi.find(y=>y.id===d.id),box=$('#pdiSug');box.innerHTML='<div class="card"><span class="spin"></span> <span class="mut sm">Pensando em ações…</span></div>';
 try{const j=await aiJSON(`${ETICA}\n\nSugira de 4 a 6 ações de desenvolvimento para um PDI. Competência: ${x.comp}. Objetivo: ${x.obj}. Metodologia: ${x.metodo}. Prazo: ${x.prazo} (hoje é ${hoje()}). Combine leituras, cursos, exercícios práticos, experiências no trabalho, simulações no Prumo Simula e acompanhamentos. Retorne JSON {"acoes":[{"t":"ação concreta","tipo":"leitura|curso|exercício|experiência|simulação|acompanhamento","prazo":"AAAA-MM-DD"}]}`);
  pdiSugs=(j.acoes||[]).slice(0,6);box.innerHTML=`<div class="card ai" style="margin-top:10px"><p class="sm mut" style="margin-bottom:8px">Sugestões da IA. Toque para adicionar.</p>${pdiSugs.map((a,i)=>`<button class="row" style="margin-bottom:6px;min-height:48px" data-a="pdiAddSug" data-id="${x.id}" data-i="${i}"><span class="grow sm">${esc(a.t)}<br><span class="xs mut">${esc(a.tipo||'')} · ${esc(fd(a.prazo))}</span></span>${ic('plus')}</button>`).join('')}</div>`}
 catch(e){box.innerHTML=`<p class="note">${esc(aiErr(e))}</p>`}};
A.pdiAddSug=(d,t)=>{const x=S.pdi.find(y=>y.id===d.id),a=pdiSugs[+d.i];x.acoes.push({id:nid(),t:a.t,resp:x.lid?lidN(x.lid).split(' ')[0]:'Eu',prazo:/^\d{4}-\d\d-\d\d$/.test(a.prazo)?a.prazo:addD(14),ok:false});save();t.remove();toast('Ação adicionada');const l=$('#pacoes');if(l){const keep=$('#pdiSug').innerHTML;render();$('#pdiSug').innerHTML=keep}};

/* ---------- reconhecimento ---------- */
V.recs=()=>({t:'Reconhecimento',act:`<button class="ib" data-a="go" data-v="recEdit" aria-label="Novo">${ic('plus')}</button>`,h:S.rec.length?`<div class="list">${[...S.rec].sort((a,b)=>b.data.localeCompare(a.data)).map(r=>`<button class="row" data-a="go" data-v="recVer" data-id="${r.id}">${ic('star','color:var(--acc)')}<span class="grow"><b style="font-weight:600">${esc(r.texto)}</b><br><span class="sm mut">${esc(lidN(r.lid)||'Equipe')} · ${esc(r.cat)} · ${esc(fd(r.data))}</span></span></button>`).join('')}</div><p class="xs mut" style="margin-top:12px">Sem competição ou ranking: cada reconhecimento é individual.</p>`:empty('star','Nenhum reconhecimento registrado.',`<button class="btn" style="margin-top:12px" data-a="go" data-v="recEdit">Reconhecer alguém</button>`)});
V.recEdit=p=>({t:'Reconhecer',h:`<label class="f">Quem${lidSel('rc_lid',p.lid||'',[['','A equipe toda']])}</label><label class="f">Categoria${sel('rc_cat',CAT_REC)}</label>
 <label class="f">O que a pessoa fez<textarea id="rc_txt" placeholder="Seja específico: o que fez e qual foi o impacto"></textarea></label>
 <button class="btn gold full" data-a="recGerar">${ic('spark')} Gerar mensagem com IA</button>
 <label class="f" style="margin-top:12px">Mensagem<textarea id="rc_msg" style="min-height:130px"></textarea></label>
 <button class="btn full" data-a="recSalvar">Salvar reconhecimento</button>`});
A.recGerar=async()=>{const l=lidN(val('rc_lid')).split(' ')[0]||'equipe',t=val('rc_txt');if(!t)return toast('Descreva o que a pessoa fez.');const m=$('#rc_msg');m.value='Gerando…';
 try{const x=await ai(`${ETICA}\n\nEscreva uma mensagem de reconhecimento curta (até 60 palavras), calorosa e específica, do líder para ${l}. Categoria: ${val('rc_cat')}. Fato: ${t}. Mencione o comportamento e o impacto. Sem exageros, sem comparar com colegas. Apenas a mensagem.`,{tier:'quick',onText:({text})=>{m.value=text}});m.value=x}catch(e){m.value='';toast(aiErr(e))}};
A.recSalvar=()=>{const texto=val('rc_txt');if(!texto)return toast('Descreva o reconhecimento.');const id=nid();S.rec.push({id,lid:val('rc_lid')||null,cat:val('rc_cat'),texto:texto.slice(0,90),msg:val('rc_msg')||texto,data:hoje()});save();stack.pop();go('recVer',{id})};
V.recVer=p=>{const r=S.rec.find(x=>x.id===p.id);if(!r)return {t:'Reconhecimento',h:''};return {t:'Reconhecimento',h:`
 <div class="cardvis"><span class="lg">${LOGO}</span><p style="color:#C4A46B;font-weight:600;font-size:13px">${esc(r.cat)}</p><h2 style="margin:8px 0 12px">${esc(lidN(r.lid)||'Equipe')}, obrigado!</h2><p style="line-height:1.6;color:#E8EFEC">${esc(r.msg)}</p><p class="xs" style="margin-top:16px;color:#9FB0AB">${esc(S.perfil.nome||'Seu líder')} · ${esc(fd(r.data))} · Prumo Feedback</p></div>
 <div class="btns"><button class="btn" data-a="recCopy" data-id="${r.id}">${ic('copy')} Copiar mensagem</button><button class="btn danger" data-a="recDel" data-id="${r.id}">Excluir</button></div>
 <p class="note">Compartilhe apenas com autorização da pessoa. No app nativo, o cartão poderá ser enviado como imagem.</p>`}};
A.recCopy=d=>copy(S.rec.find(x=>x.id===d.id).msg);
A.recDel=d=>confirmBox('Excluir este reconhecimento?','Excluir',()=>{S.rec=S.rec.filter(x=>x.id!==d.id);save();back()});

/* ---------- agenda ---------- */
let agView='lista',agMes=hoje().slice(0,7),agDia=hoje();
V.agenda=p=>{const all=agendaItems(),t=hoje();let h='';
 const item=i=>`<div class="row" style="min-height:52px">${i.k==='ag'||i.k==='ev'||i.k==='fbac'?`<input type="checkbox" data-a="agTog" data-k="${i.k}" data-id="${i.id}" ${i.ok?'checked':''} style="width:22px;min-height:22px;flex:none" aria-label="Concluir">`:ic(i.k==='reun'?'cal':i.k==='pdi'?'pdi':'goal')}<span class="grow sm" style="${i.ok?'text-decoration:line-through;opacity:.6':''}">${esc(i.t)}<br><span class="xs ${!i.ok&&i.data<t?'':'mut'}" style="${!i.ok&&i.data<t?'color:var(--bad)':''}">${esc(i.tipo)} · ${esc(fd(i.data))}${i.hora?' '+esc(i.hora):''}${!i.ok&&i.data<t?' · atrasado':''}</span></span>${i.k==='ag'?`<button class="ib" data-a="agRemarcar" data-id="${i.id}" aria-label="Reagendar">${ic('cal')}</button>`:''}</div>`;
 if(p.f==='atrasados'&&agView==='lista'){const a=all.filter(i=>!i.ok&&i.data<t);h=a.length?`<div class="list">${a.map(item).join('')}</div>`:empty('check','Nenhum atraso.')}
 else if(agView==='lista'){const fut=all.filter(i=>i.data>=addD(-7)&&(!i.ok||i.data>=t));const g={};fut.forEach(i=>(g[i.data]=g[i.data]||[]).push(i));h=Object.keys(g).length?Object.keys(g).sort().map(d=>`<p class="sm" style="margin:14px 0 6px;font-weight:600">${esc(d===t?'Hoje':fdl(d))}</p><div class="list">${g[d].map(item).join('')}</div>`).join(''):empty('cal','Agenda livre.')}
 else if(agView==='dia'){const a=all.filter(i=>i.data===agDia);h=`<div style="display:flex;align-items:center;gap:8px;margin-bottom:10px"><button class="ib" data-a="agNav" data-n="-1" aria-label="Dia anterior">${ic('back')}</button><b style="flex:1;text-align:center">${esc(fdl(agDia))}</b><button class="ib" data-a="agNav" data-n="1" aria-label="Próximo dia">${ic('chev')}</button></div>${a.length?`<div class="list">${a.map(item).join('')}</div>`:empty('cal','Nada neste dia.')}`}
 else if(agView==='semana'){const st=new Date(agDia+'T12:00');st.setDate(st.getDate()-st.getDay());const ds=[...Array(7)].map((_,i)=>iso(new Date(st.getTime()+i*864e5)));h=`<div style="display:flex;align-items:center;gap:8px;margin-bottom:10px"><button class="ib" data-a="agNav" data-n="-7" aria-label="Semana anterior">${ic('back')}</button><b style="flex:1;text-align:center">${esc(fd(ds[0]))} a ${esc(fd(ds[6]))}</b><button class="ib" data-a="agNav" data-n="7" aria-label="Próxima semana">${ic('chev')}</button></div>`+ds.map(d=>{const a=all.filter(i=>i.data===d);return `<p class="sm" style="margin:12px 0 6px;font-weight:600">${esc(new Date(d+'T12:00').toLocaleDateString('pt-BR',{weekday:'short',day:'numeric'}))}</p>${a.length?`<div class="list">${a.map(item).join('')}</div>`:'<p class="xs mut">—</p>'}`}).join('')}
 else{const [y,m]=agMes.split('-').map(Number),f=new Date(y,m-1,1),n=new Date(y,m,0).getDate(),off=f.getDay();const has=new Set(all.map(i=>i.data));h=`<div style="display:flex;align-items:center;gap:8px;margin-bottom:10px"><button class="ib" data-a="agMes" data-n="-1" aria-label="Mês anterior">${ic('back')}</button><b style="flex:1;text-align:center;text-transform:capitalize">${esc(f.toLocaleDateString('pt-BR',{month:'long',year:'numeric'}))}</b><button class="ib" data-a="agMes" data-n="1" aria-label="Próximo mês">${ic('chev')}</button></div><div class="cal">${['D','S','T','Q','Q','S','S'].map(x=>`<span class="xs mut">${x}</span>`).join('')}${'<span></span>'.repeat(off)}${[...Array(n)].map((_,i)=>{const d=`${agMes}-${String(i+1).padStart(2,'0')}`;return `<button class="d ${d===t?'t':''} ${has.has(d)?'has':''}" data-a="agPick" data-d="${d}">${i+1}</button>`}).join('')}</div><p class="sm" style="margin:14px 0 6px;font-weight:600">${esc(fdl(agDia))}</p>${(()=>{const a=all.filter(i=>i.data===agDia);return a.length?`<div class="list">${a.map(item).join('')}</div>`:'<p class="sm mut">Nada neste dia.</p>'})()}`}
 return {t:'Agenda',act:`<button class="ib" data-a="agNovo" aria-label="Novo compromisso">${ic('plus')}</button>`,h:`<div class="seg">${[['dia','Dia'],['semana','Semana'],['mes','Mês'],['lista','Lista']].map(v=>`<button class="${agView===v[0]?'on':''}" data-a="agView" data-x="${v[0]}">${v[1]}</button>`).join('')}</div>${h}<p class="note">Integração com Google Agenda e Apple Calendário será opcional na versão das lojas.</p>`}};
A.agView=d=>{agView=d.x;stack[stack.length-1].p={};render()};
A.agNav=d=>{agDia=addD(+d.n,agDia);render()};
A.agMes=d=>{const [y,m]=agMes.split('-').map(Number);const n=new Date(y,m-1+(+d.n),1);agMes=iso(n).slice(0,7);render()};
A.agPick=d=>{agDia=d.d;render()};
A.agTog=(d,t)=>{if(d.k==='ag')S.ag.find(x=>x.id===d.id).ok=t.checked;if(d.k==='ev')S.ev.find(x=>x.id===d.id).status=t.checked?'concluido':'pendente';if(d.k==='fbac')S.ev.find(x=>x.id===d.id).acompOk=t.checked;save();render()};
A.agNovo=()=>sheet(`<h3>Novo compromisso</h3><label class="f" style="margin-top:12px">Título<input id="a_t"></label><label class="f">Tipo${sel('a_tipo',['Compromisso pessoal','Treinamento','Integração','Simulação','Feedback','Reunião'])}</label><div style="display:grid;grid-template-columns:1fr 1fr;gap:10px"><label class="f">Data<input type="date" id="a_d" value="${esc(agDia)}"></label><label class="f">Hora<input type="time" id="a_h"></label></div><label class="f">Recorrência${sel('a_r',[['','Não repetir'],'Diária','Semanal','Mensal'])}</label><div class="btns"><button class="btn line" data-a="closeSheet">Cancelar</button><button class="btn" style="flex:1" data-a="agSalvar">Salvar</button></div>`);
A.agSalvar=()=>{const t=val('a_t');if(!t)return toast('Informe o título.');const r=val('a_r'),d0=val('a_d')||hoje(),n=r?({'Diária':7,'Semanal':6,'Mensal':4})[r]:1,st=({'Diária':1,'Semanal':7,'Mensal':30})[r]||0;for(let i=0;i<n;i++)S.ag.push({id:nid(),titulo:t,tipo:val('a_tipo'),data:addD(i*st,d0),hora:val('a_h'),recorr:r,ok:false});save();closeSheet();toast(n>1?`${n} ocorrências criadas`:'Compromisso criado');render()};
A.agRemarcar=d=>{const a=S.ag.find(x=>x.id===d.id);sheet(`<h3>Reagendar</h3><p class="sm mut" style="margin:6px 0 10px">${esc(a.titulo)}</p><label class="f">Nova data<input type="date" id="rm_d" value="${esc(a.data)}"></label><div class="btns"><button class="btn danger" data-a="agDel" data-id="${a.id}">Excluir</button><button class="btn" style="flex:1" data-a="agRmOk" data-id="${a.id}">Salvar</button></div>`)};
A.agRmOk=d=>{S.ag.find(x=>x.id===d.id).data=val('rm_d');save();closeSheet();render()};
A.agDel=d=>{S.ag=S.ag.filter(x=>x.id!==d.id);save();closeSheet();render()};

/* ---------- metas ---------- */
const metaProg=m=>{const e=parseFloat(String(m.esperado).replace(',','.')),a=parseFloat(String(m.atual).replace(',','.'));return e>0&&!isNaN(a)?Math.max(0,Math.min(100,Math.round(a/e*100))):0};
let metaF='todas';
V.metas=()=>{const L=S.metas.filter(m=>metaF==='todas'||m.escopo===metaF);return {t:'Metas',act:`<button class="ib" data-a="go" data-v="metaEdit" aria-label="Nova meta">${ic('plus')}</button>`,h:`<div class="seg">${['todas','Pessoal','Individual','Equipe'].map(f=>`<button class="${metaF===f?'on':''}" data-a="metaF" data-f="${f}">${f==='todas'?'Todas':f}</button>`).join('')}</div>
 ${L.length?`<div class="list">${L.map(m=>{const late=m.status!=='concluída'&&m.prazo<hoje();return `<button class="row" data-a="go" data-v="metaEdit" data-id="${m.id}" style="display:block"><div style="display:flex;justify-content:space-between;gap:8px"><b style="font-weight:600">${esc(m.titulo)}</b><span class="tag ${late?'b':m.status==='concluída'?'o':m.prio==='Alta'?'w':''}">${late?'atrasada':esc(m.status)}</span></div><p class="xs mut" style="margin:4px 0 8px">${esc(m.escopo)} · ${esc(m.resp)} · ${esc(m.indic)}: ${esc(m.atual||0)} de ${esc(m.esperado)} · prazo ${esc(fd(m.prazo))}</p><div class="prog"><i style="width:${metaProg(m)}%"></i></div></button>`}).join('')}</div>`:empty('goal','Nenhuma meta neste filtro.')}`}};
A.metaF=d=>{metaF=d.f;render()};
V.metaEdit=p=>{const m=S.metas.find(x=>x.id===p.id)||{escopo:'Individual',prio:'Média',status:'não iniciada',prazo:addD(30)};return {t:p.id?'Editar meta':'Nova meta',h:`
 <label class="f">Título<input id="mt_t" value="${esc(m.titulo)}"></label><label class="f">Descrição<textarea id="mt_d">${esc(m.desc)}</textarea></label>
 <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px"><label class="f">Escopo${sel('mt_e',['Pessoal','Individual','Equipe'],m.escopo)}</label><label class="f">Responsável<input id="mt_r" value="${esc(m.resp)}" list="dl_lid"><datalist id="dl_lid"><option value="Eu"><option value="Equipe">${ativos().map(l=>`<option value="${esc(l.nome)}">`).join('')}</datalist></label></div>
 <label class="f">Indicador<input id="mt_i" value="${esc(m.indic)}" placeholder="Ex.: NPS, % de entregas no prazo"></label>
 <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px"><label class="f">Resultado esperado<input id="mt_es" inputmode="decimal" value="${esc(m.esperado)}"></label><label class="f">Resultado atual<input id="mt_at" inputmode="decimal" value="${esc(m.atual)}"></label></div>
 <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px"><label class="f">Prazo<input type="date" id="mt_p" value="${esc(m.prazo)}"></label><label class="f">Prioridade${sel('mt_pr',['Alta','Média','Baixa'],m.prio)}</label></div>
 <label class="f">Status${sel('mt_s',['não iniciada','em andamento','concluída','cancelada'],m.status)}</label>
 <div class="btns"><button class="btn full" data-a="metaSalvar" data-id="${p.id||''}">Salvar</button>${p.id?`<button class="btn danger full" data-a="metaDel" data-id="${p.id}">Excluir</button>`:''}</div>`}};
A.metaSalvar=d=>{const titulo=val('mt_t');if(!titulo)return toast('Informe o título.');const o={titulo,desc:val('mt_d'),escopo:val('mt_e'),resp:val('mt_r'),indic:val('mt_i'),esperado:val('mt_es'),atual:val('mt_at'),prazo:val('mt_p'),prio:val('mt_pr'),status:val('mt_s')};if(d.id)Object.assign(S.metas.find(x=>x.id===d.id),o);else S.metas.push({id:nid(),...o});save();toast('Meta salva');back()};
A.metaDel=d=>confirmBox('Excluir esta meta?','Excluir',()=>{S.metas=S.metas.filter(x=>x.id!==d.id);save();back()});

/* ditado: voz nativa quando houver; senão, ditado do teclado do celular */
function ditado(id){const el=document.getElementById(id);if(!el)return;el.focus();
 const ios=/iPhone|iPad|iPod/i.test(navigator.userAgent),and=/Android/i.test(navigator.userAgent);
 const como=ios?'No teclado do iPhone, toque no ícone de microfone (no canto inferior, ao lado da barra de espaço) e fale. O texto aparece no campo; depois toque em enviar.':and?'No teclado do Android, toque no ícone de microfone e fale. O texto aparece no campo; depois toque em enviar.':'Neste navegador, use o ditado do sistema (no Mac: tecla Fn duas vezes; no Windows: Win + H), ou abra no Chrome para falar direto pelo app.';
 if(S.cfg.ditadoVisto){toast(ios||and?'Toque no microfone do teclado e fale':'Use o ditado do sistema para falar');return}
 S.cfg.ditadoVisto=1;save();
 sheet(`<div style="display:flex;gap:12px;align-items:center"><span class="av" style="width:48px;height:48px;background:var(--our);color:#1d1a12">${ic('mic')}</span><h3>Fale em vez de digitar</h3></div><p style="margin-top:12px;line-height:1.6">${esc(como)}</p><p class="note">Se o seu navegador não transcrever direto, use o microfone do teclado do celular: ele também transforma sua fala em texto.</p><div class="btns"><button class="btn full" data-a="ditadoOk" data-id="${id}">Entendi, vou falar</button></div>`)}
A.ditadoOk=d=>{closeSheet();const el=document.getElementById(d.id);if(el)el.focus()};
